parameters.jsCode:
// Speicherort aus der Oberfläche (Einstellungen › Eigener Speicherort, Ablage der Belege auf der Seite Belege). Herkunft prüfen wie bei ALLY 8, Sitzung aus dem Cookie.
// Das Passwort geht nur an die Prüfanfragen und an die n8n-Zugangsdaten, nie in die Datenbank. Dieser Ablauf speichert keine Ausführungsdaten.
// Leeres Passwort (Stefan 17.10.2026): Ally prüft und arbeitet mit dem gespeicherten Passwort, wenn der Benutzer gleich bleibt (prüft die Datenbank).
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben). n8n ist nur über traefik erreichbar,
// traefik leitet nur eingerichtete Adressen weiter. So gelten die bisherige n8n-Adresse und die eigene Adresse der Oberfläche ohne feste Werte (17.10.2026).
// Migration 89 (Stefan 22.10.2026): verbinden = Schritt 1 „Verbindung prüfen“ (nur anmelden und Zugangsdaten setzen; umgestellt wird erst mit dem gewählten Ordner).
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($json.headers || {}).host || '').trim().toLowerCase());
const h = $json.headers || {};
const b = $json.body || {};
const herkunft = String(h.origin || '');
const verweis = String(h.referer || '');
// Verweis nur mit Trennzeichen nach dem Seitenpfad (Ende, '/', '?' oder '#'), sonst gälte auch /webhook/web-xyz (Stefan 17.10.2026)
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const s = v => String(v ?? '').trim();
const aktion = herkunftOk && ['speichern', 'server', 'belege_ordner', 'verbinden'].includes(s(b.aktion)) ? s(b.aktion) : 'ungueltig';
const pw = String(b.passwort ?? '');
const daten = {
  name: s(b.name), adresse: s(b.adresse).toLowerCase(), benutzer: s(b.benutzer),
  ordner: s(b.ordner), ordner_belege: s(b.ordner_belege), passwort_laenge: String(pw.length), pw_gespeichert: pw.length === 0 ? '1' : ''
};
return [{ json: { token, aktion, daten: JSON.stringify(daten), pw } }];

parameters.query:
SELECT CASE WHEN $2::text = 'ungueltig' THEN '{"ok": false, "ungueltig": true}'::jsonb ELSE ablage_web_vorbereiten($1::text, $2::text, $3::jsonb) END AS v,
  -- Produktname (Einstellung produkt_name) fuer Pruef- und Fehlertexte (Stefan 18.10.2026)
  produkt_name() AS produkt_name;

parameters.jsCode:
// Prüfanfragen: Ordner, die es schon geben muss, werden zuerst nachgesehen (PROPFIND). Nur wenn alle da sind, geht es mit
// den Prüfdateien weiter. So gibt es bei falschem Passwort nur einen Versuch je Ordner.
const F = $('Formular prüfen').first().json;
const V = $('Vorbereiten').first().json.v || {};
const auth = 'Basic ' + Buffer.from(String(V.benutzer) + ':' + F.pw, 'utf8').toString('base64');
const enc = p => String(p).split('/').filter(Boolean).map(encodeURIComponent).join('/');
return (V.ordner || []).filter(o => o.pruefen && !o.anlegen).map(o => ({ json: { bereich: o.bereich, name: o.name, ordner: o.ordner, url_ordner: V.adresse + '/' + enc(o.ordner) + '/', auth } }));

// Ordner auswerten: Sind alle vorhandenen Ordner da und als Ordner erkennbar (Antwort 207 mit collection)?
const R = $input.all();
const P = $('Prüfanfragen').all();
const ok = P.length > 0 && P.every((p, i) => {
  const r = R[i] && R[i].json || {};
  return Number(r.statusCode) === 207 && /<(?:[\w-]+:)?collection\s*\/?>/.test(String(r.data || r.body || ''));
});
return [{ json: { alle_ok: ok } }];

// Prüfdateien: je zu prüfendem Ordner eine kleine Datei schreiben, Größe prüfen, wieder löschen.
// Der Standard-Unterordner für die Belege (anlegen) wird vorher angelegt.
const F = $('Formular prüfen').first().json;
const V = $('Vorbereiten').first().json.v || {};
const auth = 'Basic ' + Buffer.from(String(V.benutzer) + ':' + F.pw, 'utf8').toString('base64');
const enc = p => String(p).split('/').filter(Boolean).map(encodeURIComponent).join('/');
const marke = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
// Produktname aus der Einstellung produkt_name; ohne Namen neutraler Text (Stefan 18.10.2026)
const P = String($('Vorbereiten').first().json.produkt_name || '').trim();
const inhalt = (P ? P + ' prüft den Speicherort.' : 'Prüfung des Speicherorts.') + ' Diese Datei wird sofort wieder gelöscht.';
return (V.ordner || []).filter(o => o.pruefen).map(o => {
  const basis = V.adresse + '/' + enc(o.ordner);
  return { json: { bereich: o.bereich, name: o.name, ordner: o.ordner, anlegen: !!o.anlegen, url_ordner: basis + '/', url_datei: basis + '/.ally-pruefung-' + marke + '.txt',
    inhalt, bytes: Buffer.byteLength(inhalt, 'utf8'), auth } };
});

// Prüfung auswerten: verständliche Meldung. Nicht erreichbar, Anmeldung, Ordner fehlt, Anlegen, Schreiben, Größe; Löschen nur als Hinweis.
// Ohne neues Passwort kommen alle Antworten aus "Speicherort prüfen (gespeichert)" und werden hier den Schritten zugeordnet.
// Produktname aus der Einstellung produkt_name; ohne Namen neutraler Text (Stefan 18.10.2026)
const PN = String($('Vorbereiten').first().json.produkt_name || '').trim();
const lauf = n => $(n).isExecuted ? $(n).all() : [];
let P, O, T, U, W, H, D;
if ($('Speicherort prüfen (gespeichert)').isExecuted) {
  const S = $('Prüfschritte (gespeichert)').all(), G = $('Speicherort prüfen (gespeichert)').all();
  const nach = s => S.map((x, k) => ({ x, r: G[k] })).filter(e => e.x.json.schritt === s);
  P = nach('ordner').map(e => e.x); O = nach('ordner').map(e => e.r);
  // Schreiben nur auswerten, wenn alle Ordner da waren (wie mit neuem Passwort)
  const da = P.length > 0 && O.every(r => Number(r && r.json && r.json.statusCode) === 207 && /<(?:[\w-]+:)?collection\s*\/?>/.test(String(r.json.data || r.json.body || '')));
  T = da ? nach('schreiben').map(e => e.x) : [];
  U = da ? nach('anlegen').map(e => e.r) : []; W = da ? nach('schreiben').map(e => e.r) : []; H = da ? nach('nachsehen').map(e => e.r) : []; D = da ? nach('loeschen').map(e => e.r) : [];
} else {
  P = $('Prüfanfragen').all();
  O = lauf('Ordner nachsehen'); T = lauf('Prüfdateien'); U = lauf('Unterordner anlegen'); W = lauf('Prüfdatei schreiben'); H = lauf('Prüfdatei nachsehen'); D = lauf('Prüfdatei löschen');
}
const st = r => Number(r && r.json && r.json.statusCode) || 0;
const fehlerMeldung = r => { const e = r && r.json && r.json.error; return e ? String(e.message || e.description || e).slice(0, 120) : ''; };
const kopf = (h, k) => { h = h || {}; const f = Object.keys(h).find(x => x.toLowerCase() === k); return f ? h[f] : undefined; };
const was = j => 'Ordner ' + j.name + ' (' + j.ordner + '): ';
const texte = [];
let rest = false;
P.forEach((p, i) => {
  const o = O[i], oc = st(o);
  if (!oc) { texte.push('Der Speicherort ist nicht erreichbar. Adresse prüfen, und ob der ' + (PN ? PN + '-Server' : 'Server') + ' ihn erreichen kann' + (fehlerMeldung(o) ? ' (' + fehlerMeldung(o) + ')' : '') + '.'); return; }
  if (oc === 401) { texte.push('Anmeldung abgelehnt. Anmeldename oder Passwort stimmen nicht.'); return; }
  if (oc === 403) { texte.push(was(p.json) + 'Mit diesem Anmeldenamen lässt sich dieser Ordner nicht öffnen.'); return; }
  if (oc === 404) { texte.push(was(p.json) + 'Diesen Ordner gibt es nicht. Bitte zuerst auf dem Speicher anlegen.'); return; }
  if (oc !== 207) { texte.push(was(p.json) + 'Der Speicherort antwortet nicht wie ein WebDAV-Speicher (Status ' + oc + '). Ist WebDAV eingeschaltet und die Adresse richtig?'); return; }
  if (!/<(?:[\w-]+:)?collection\s*\/?>/.test(String(o.json.data || o.json.body || ''))) texte.push(was(p.json) + 'Unter diesem Pfad liegt eine Datei, kein Ordner.');
});
// Schreiben nur, wenn alle Ordner da waren
T.forEach((t, i) => {
  const j = t.json;
  if (j.anlegen && ![201, 405].includes(st(U[i]))) { texte.push(was(j) + 'Der Ordner konnte nicht angelegt werden (' + (st(U[i]) ? 'Status ' + st(U[i]) : 'keine Antwort') + ').'); return; }
  const wc = st(W[i]);
  if (![200, 201, 204].includes(wc)) { texte.push(was(j) + 'Schreiben nicht möglich (' + (wc === 401 || wc === 403 ? 'keine Schreibrechte' : wc === 507 ? 'Speicher voll' : wc ? 'Status ' + wc : 'keine Antwort' + (fehlerMeldung(W[i]) ? ': ' + fehlerMeldung(W[i]) : '')) + ').'); return; }
  const hc = st(H[i]), laenge = Number(kopf(H[i] && H[i].json && H[i].json.headers, 'content-length'));
  if (hc !== 200 || laenge !== j.bytes) texte.push(was(j) + 'Die Prüfdatei ist nicht vollständig angekommen.');
  if (![200, 204, 404].includes(st(D[i]))) rest = true;
});
const ok = T.length > 0 && texte.length === 0;
// Gleiche Meldungen (z. B. nicht erreichbar) nur einmal
return [{ json: { pruefung_ok: ok, pruefung_text: [...new Set(texte)].join(' '), rest } }];

// Ergebnis zusammenfassen (ohne Passwort) für "Abschließen"
// Migration 89: bei „verbinden“ zusätzlich das Ergebnis der Anmeldung (anmeldung_ok, anmeldung_text)
const F = $('Formular prüfen').first().json;
const V = $('Vorbereiten').first().json.v || {};
const api = {};
if ($('Prüfung auswerten').isExecuted) Object.assign(api, $('Prüfung auswerten').first().json);
if ($('Anmeldung auswerten').isExecuted) Object.assign(api, $('Anmeldung auswerten').first().json);
if ($('Zugangsdaten setzen').isExecuted) {
  const r = $('Zugangsdaten setzen').first().json || {};
  api.patch_status = String(r.statusCode || '');
  if (r.statusCode !== 200) api.patch_meldung = String(((r.body || {}).message) || (r.error && (r.error.message || r.error)) || '').slice(0, 300);
}
if ($('Prüfdatei ablegen (SPEICHER 1)').isExecuted) {
  const a = $('Prüfdatei ablegen (SPEICHER 1)').first().json || {};
  const l = $('Prüfdatei entfernen (SPEICHER 1)').isExecuted ? $('Prüfdatei entfernen (SPEICHER 1)').first().json || {} : {};
  api.ablegen_ok = a.ok === true;
  if (a.ok !== true) api.fehler = String(a.fehler || (a.error && (a.error.message || a.error)) || 'unbekannter Fehler').slice(0, 300);
  api.rest = a.ok === true && l.ok !== true;
}
return [{ json: { token: F.token, aktion: F.aktion, vorher: JSON.stringify(V), api: JSON.stringify(api) } }];

// Zurück auf die Seite Eigener Speicherort bzw. Belege; Sitzung wie bei ALLY 8 behandeln
const SEITE = '/webhook/web';
const F = $('Formular prüfen').first().json;
// Stelle auf der Seite (Stefan 17.10.2026): Position, offene Bereiche und Formular aus der Adresse des Formulars wieder anhängen, damit die Seite nicht nach oben springt
const ZQ = $('Formular').first().json.query || {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
const r = ($('Abschließen').isExecuted ? $('Abschließen').first().json.r : $('Vorbereiten').first().json.v) || {};
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
let ziel, cookie = '';
if (F.aktion === 'ungueltig' || r.ungueltig) ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else { ziel = SEITE + (F.aktion === 'belege_ordner' ? '?ansicht=belege#fuer-alle' : '?ansicht=speicherort'); ziel = stelle(ziel); if (F.token) cookie = keks(F.token, 2592000); }
return [{ json: { ziel, set_cookie: cookie } }];

// Prüfauftrag Belege: kleine Prüfdatei im neuen Ordner für verbuchte Belege ablegen (über SPEICHER 1 mit den gespeicherten Zugangsdaten)
// Produktname aus der Einstellung produkt_name; ohne Namen neutraler Text (Stefan 18.10.2026)
const P = String($('Vorbereiten').first().json.produkt_name || '').trim();
const marke = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
return [{ json: { aktion: 'ablegen', bereich: 'buchhaltung', pfad: '.ally-pruefung-' + marke + '.txt', text: (P ? P + ' prüft den Ordner.' : 'Prüfung des Ordners.') + ' Diese Datei wird sofort wieder gelöscht.', ueberschreiben: false } }];

// Prüfschritte ohne neues Passwort (Stefan 17.10.2026): dieselben Prüfungen wie mit neuem Passwort, aber mit den gespeicherten Zugangsdaten.
// Alle Anfragen laufen nacheinander durch einen Knoten. Fehlt ein Ordner, scheitern die folgenden Schritte ohne Wirkung, gemeldet wird der fehlende Ordner.
const V = $('Vorbereiten').first().json.v || {};
const enc = p => String(p).split('/').filter(Boolean).map(encodeURIComponent).join('/');
const marke = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
// Produktname aus der Einstellung produkt_name; ohne Namen neutraler Text (Stefan 18.10.2026)
const P = String($('Vorbereiten').first().json.produkt_name || '').trim();
const inhalt = (P ? P + ' prüft den Speicherort.' : 'Prüfung des Speicherorts.') + ' Diese Datei wird sofort wieder gelöscht.';
const ordner = (V.ordner || []).filter(o => o.pruefen);
const raus = [];
ordner.filter(o => !o.anlegen).forEach(o => raus.push({ json: { schritt: 'ordner', bereich: o.bereich, name: o.name, ordner: o.ordner, methode: 'PROPFIND', url: V.adresse + '/' + enc(o.ordner) + '/', kopf: { Depth: '0' }, inhalt: '' } }));
// Reihenfolge wie mit neuem Passwort: erst alle Ordner, dann alle Prüfdateien schreiben, dann nachsehen, dann löschen (der Speicher braucht nach dem Schreiben einen Moment)
const schritte = ordner.map(o => {
  const basis = V.adresse + '/' + enc(o.ordner), datei = basis + '/.ally-pruefung-' + marke + '.txt';
  const info = { bereich: o.bereich, name: o.name, ordner: o.ordner, anlegen: !!o.anlegen, bytes: Buffer.byteLength(inhalt, 'utf8') };
  return [{ ...info, schritt: 'anlegen', methode: o.anlegen ? 'MKCOL' : 'PROPFIND', url: basis + '/', kopf: { Depth: '0' }, inhalt: '' },
    { ...info, schritt: 'schreiben', methode: 'PUT', url: datei, kopf: {}, inhalt },
    { ...info, schritt: 'nachsehen', methode: 'HEAD', url: datei, kopf: { 'Accept-Encoding': 'identity' }, inhalt: '' },
    { ...info, schritt: 'loeschen', methode: 'DELETE', url: datei, kopf: {}, inhalt: '' }];
});
for (let k = 0; k < 4; k++) schritte.forEach(s => raus.push({ json: s[k] }));
return raus;

// Anmeldung vorbereiten (ALLY 11, Migration 89): Schritt 1 „Verbindung prüfen“ – nur die Wurzel des Speichers nachsehen (PROPFIND Depth 0) mit den eingegebenen Angaben.
// Kein Schreiben, kein Ordner. Das Passwort steht nur hier und in der Anfrage, nie in der Datenbank.
const F = $('Formular prüfen').first().json;
const V = $('Vorbereiten').first().json.v || {};
return [{ json: { url: String(V.adresse || '').replace(/\/+$/, '') + '/', auth: 'Basic ' + Buffer.from(String(V.benutzer) + ':' + F.pw, 'utf8').toString('base64') } }];

// Anmeldung auswerten (ALLY 11, Migration 89): verständliche Meldung; nur Status 207 (WebDAV antwortet) gilt als Verbindung.
const r = $input.first().json || {};
const c = Number(r.statusCode) || 0;
const PN = String($('Vorbereiten').first().json.produkt_name || '').trim();
const fm = r.error ? String(r.error.message || r.error.description || r.error).slice(0, 120) : '';
let text = '';
if (!c) text = 'Der Speicher ist nicht erreichbar. Adresse prüfen, und ob der ' + (PN ? PN + '-Server' : 'Server') + ' ihn erreichen kann' + (fm ? ' (' + fm + ')' : '') + '.';
else if (c === 401) text = 'Anmeldung abgelehnt. Anmeldename oder Passwort stimmen nicht.';
else if (c === 403) text = 'Mit diesem Anmeldenamen lässt sich der Speicher nicht öffnen.';
else if (c !== 207) text = 'Der Speicher antwortet nicht wie ein WebDAV-Speicher (Status ' + c + '). Ist WebDAV eingeschaltet und die Adresse richtig?';
return [{ json: { anmeldung_ok: c === 207, anmeldung_text: text } }];
